Gb={'1':one,'t':t,'s':s,'1/t':1/t,'t2':t**2,'tL':t*L,'1/s':1/s}
def run(Fk,Gk,Hk=[]):
    cols=[Fb[k] for k in Fk]+[Gb[k]*A**2 for k in Gk]+[Gb[k]*A for k in Hk]
    names=['F'+k for k in Fk]+['G'+k for k in Gk]+['H'+k for k in Hk]
    X=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt), dict(zip(names,np.round(c,4)))
